output_text:
[
  {
    "id": "take_entry_cart",
    "text": "A shopper must take the entrance cart before doing the shopping trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "pushing_cart": "hasCart"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "pushing_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "use_cart_for_shelf_pickups",
    "text": "Items may only be picked up from shelves while the shopper is pushing a cart.",
    "abstraction": {
      "state_properties": {
        "pushing_cart": "hasCart",
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "shelf_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "cartless_shelf_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_shelf_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Shoppers should not carry goods by hand; goods should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "pushing_cart": "hasCart"
      },
      "events": {
        "hand_pickup": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "or": [
          "carrying_by_hand",
          "hand_pickup"
        ]
      }
    }
  },
  {
    "id": "return_cart_after_item",
    "text": "After picking up any item, the shopper must eventually return the cart to the northwest return bay.",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "cart_in_return_bay": "cartAt(0,1)",
        "pushing_cart": "hasCart"
      },
      "events": {
        "shelf_pickup": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "park_cart_in_return_bay": {
          "pre": {
            "and": [
              "return_bay",
              "LEAVE_CART"
            ]
          },
          "post": "cart_in_return_bay"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "shelf_pickup",
      "discharge": "park_cart_in_return_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A cart may only be left at the designated return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "return_bay": "at(0,1)",
        "outside_return_bay": {
          "not": "return_bay"
        }
      },
      "events": {
        "leave_cart": {
          "pre": "LEAVE_CART",
          "post": null
        },
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "exit_only_after_cart_returned",
    "text": "The shopper may exit only after the cart is stationed in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_in_return_bay": "cartAt(0,1)",
        "cart_not_returned": {
          "not": "cart_in_return_bay"
        }
      },
      "events": {
        "attempt_exit_without_returned_cart": {
          "pre": {
            "and": [
              "EXIT",
              "cart_not_returned"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "attempt_exit_without_returned_cart"
    }
  },
  {
    "id": "no_reinteraction_after_return",
    "text": "Once the cart is parked in the return bay, the shopper should not perform any further store interactions before exiting.",
    "abstraction": {
      "state_properties": {
        "cart_in_return_bay": "cartAt(0,1)"
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "cart_in_return_bay",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "cart_return_corridor_no_turnaway",
    "text": "While pushing a cart in the west-wall return corridor, the shopper must not turn east or south away from the return bay.",
    "abstraction": {
      "state_properties": {
        "west_wall_return_corridor": {
          "or": [
            "at(0,1)",
            "at(0,2)",
            "at(0,3)",
            "at(0,4)"
          ]
        },
        "pushing_cart": "hasCart",
        "pushing_cart_in_return_corridor": {
          "and": [
            "pushing_cart",
            "west_wall_return_corridor"
          ]
        }
      },
      "events": {
        "turn_away_from_return_bay_with_cart": {
          "pre": {
            "and": [
              "pushing_cart_in_return_corridor",
              {
                "or": [
                  "E",
                  "S"
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "turn_away_from_return_bay_with_cart"
    }
  }
]
